export type Side = 0 | 1;
export type Phase = "waiting" | "serve" | "rally" | "point" | "gameover";

export interface Vec3 { x: number; y: number; z: number }
export interface PaddleInput {
  x: number; y: number; z: number;
  /** Kept for wire compatibility with older clients; spin is now generated by racket motion. */
  power: boolean; slice: boolean; serve: boolean;
}
export interface PaddleState extends Vec3 {
  vx: number; vy: number; vz: number;
  prevX: number; prevY: number; prevZ: number;
  cooldown: number;
  power: boolean; slice: boolean;
}
export interface BallState {
  p: Vec3; v: Vec3; spin: Vec3;
  lastHitter: Side; bounces: number; firstBounce: Side | null; serve: boolean;
}
export interface SimEvent { type: "hit" | "bounce" | "net" | "point" | "game" | "serve"; side?: Side; p?: Vec3 }
export interface MatchState {
  phase: Phase; ball: BallState; paddles: [PaddleState, PaddleState];
  scores: [number, number]; games: [number, number]; gameNumber: number; server: Side;
  message: string; eventId: number; event: SimEvent | null; winner: Side | null;
  lastPoint: Side | null; rallyHits: number;
}
export interface PlayerSettings { name: string; kit: string; paddle: string; ball: string }
export const DEFAULT_SETTINGS: PlayerSettings = { name: "Игрок", kit: "#27d3a2", paddle: "#ef476f", ball: "#f7fbff" };
export const TABLE = Object.freeze({ width: 1.525, length: 2.74, y: 0.76, netHeight: 0.1525, ballRadius: 0.02 });
export const DEFAULT_INPUT: PaddleInput = { x: 0, y: 1.16, z: 0.92, power: false, slice: false, serve: false };

const GRAVITY = 9.81;
const BALL_MASS = 0.0027;
const BALL_RADIUS = TABLE.ballRadius;
const BALL_INERTIA = 0.4 * BALL_MASS * BALL_RADIUS * BALL_RADIUS;
const AIR_DRAG = 0.045;
const MAGNUS = 0.00030;
const AIR_SPIN_DECAY = 0.12;
const TABLE_RESTITUTION = 0.88;
const PADDLE_RESTITUTION = 0.86;
const PADDLE_FRICTION = 0.72;
const TABLE_FRICTION = 0.24;
const FIXED_STEP = 1 / 240;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
const other = (side: Side): Side => side === 0 ? 1 : 0;
const sideSign = (side: Side) => side === 0 ? 1 : -1;
const dot = (a: Vec3, b: Vec3) => a.x*b.x + a.y*b.y + a.z*b.z;
const cross = (a: Vec3, b: Vec3): Vec3 => ({ x: a.y*b.z-a.z*b.y, y: a.z*b.x-a.x*b.z, z: a.x*b.y-a.y*b.x });
const addScaled = (a: Vec3, b: Vec3, s: number): Vec3 => ({ x:a.x+b.x*s, y:a.y+b.y*s, z:a.z+b.z*s });
const length = (v: Vec3) => Math.hypot(v.x,v.y,v.z);
const normalize = (v: Vec3): Vec3 => { const l=length(v)||1; return {x:v.x/l,y:v.y/l,z:v.z/l}; };
function mulberry32(seed: number) { let a=seed>>>0; return () => { a|=0; a=(a+0x6d2b79f5)|0; let t=Math.imul(a^(a>>>15),1|a); t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; }; }
function makePaddle(side: Side): PaddleState { const z=sideSign(side)*0.92; return {x:0,y:1.16,z,vx:0,vy:0,vz:0,prevX:0,prevY:1.16,prevZ:z,cooldown:0,power:false,slice:false}; }

/**
 * Deterministic table-tennis simulation in metres and seconds.
 * Ball flight includes quadratic aerodynamic drag and Magnus lift; table and
 * racket impacts use friction impulses that exchange linear and angular momentum.
 */
export class TableTennisSim {
  state: MatchState;
  private inputs: [PaddleInput, PaddleInput];
  private random: () => number;
  private pointTimer = 0;
  private serveTimer = 0;
  private newGame = false;
  private accumulator = 0;

  constructor(seed = 2026) {
    this.random = mulberry32(seed);
    this.inputs = [{...DEFAULT_INPUT},{...DEFAULT_INPUT,z:-0.92}];
    this.state = {
      phase:"waiting", ball:{p:{x:0,y:1.12,z:1.25},v:{x:0,y:0,z:0},spin:{x:0,y:0,z:0},lastHitter:0,bounces:0,firstBounce:null,serve:true},
      paddles:[makePaddle(0),makePaddle(1)],scores:[0,0],games:[0,0],gameNumber:1,server:0,
      message:"Ожидание игроков",eventId:0,event:null,winner:null,lastPoint:null,rallyHits:0,
    };
  }

  startMatch(): void {
    this.state.scores=[0,0]; this.state.games=[0,0]; this.state.gameNumber=1;
    this.state.winner=null; this.state.lastPoint=null; this.state.server=0; this.newGame=false; this.accumulator=0;
    this.prepareServe("Первая подача");
  }

  setInput(side: Side, input: PaddleInput): void {
    const target=this.inputs[side], sign=sideSign(side);
    target.x=clamp(Number.isFinite(input.x)?input.x:0,-0.98,0.98);
    target.y=clamp(Number.isFinite(input.y)?input.y:1.16,0.84,1.7);
    target.z=clamp(Number.isFinite(input.z)?input.z:sign*0.92,sign>0?0.72:-1.12,sign>0?1.12:-0.72);
    target.power=false; target.slice=false; target.serve=Boolean(input.serve);
  }
  getInput(side: Side): PaddleInput { return this.inputs[side]; }

  private emit(type: SimEvent["type"], side?: Side, p?: Vec3): void { this.state.eventId++; this.state.event={type,side,p:p?{...p}:undefined}; }
  private prepareServe(message: string): void {
    if(this.newGame){this.newGame=false;this.state.gameNumber++;this.state.scores=[0,0];}
    const total=this.state.scores[0]+this.state.scores[1], deuce=this.state.scores[0]>=10&&this.state.scores[1]>=10;
    const turn=deuce?total:Math.floor(total/2);
    this.state.server=((turn+this.state.gameNumber-1)%2) as Side;
    const server=this.state.server, sign=sideSign(server), p=this.state.paddles[server], b=this.state.ball;
    this.state.phase="serve";this.state.message=message;this.state.lastPoint=null;this.state.rallyHits=0;
    this.serveTimer=0;this.pointTimer=0;
    b.p={x:p.x,y:Math.max(1.08,p.y+0.08),z:sign*1.2};b.v={x:0,y:0,z:0};b.spin={x:0,y:0,z:0};
    b.lastHitter=server;b.bounces=0;b.firstBounce=null;b.serve=true;
    for(const paddle of this.state.paddles)paddle.cooldown=0;
  }

  /** Accepts variable frame dt but advances the authoritative model at 240 Hz. */
  step(dt: number): void {
    this.accumulator=Math.min(this.accumulator+Math.max(0,Math.min(dt,0.1)),0.08);
    while(this.accumulator>=FIXED_STEP){this.stepFixed(FIXED_STEP);this.accumulator-=FIXED_STEP;}
  }

  private stepFixed(dt:number):void{
    const s=this.state;if(s.phase==="waiting"||s.phase==="gameover")return;
    this.updatePaddles(dt);
    if(s.phase==="point"){
      this.pointTimer-=dt;if(this.pointTimer<=0)this.prepareServe(this.newGame?`Партия ${s.gameNumber+1}`:"Следующая подача");return;
    }
    if(s.phase==="serve"){
      this.serveTimer+=dt;const server=s.server,sign=sideSign(server),p=s.paddles[server];
      s.ball.p.x=p.x;s.ball.p.y=Math.max(1.06,p.y+0.1+Math.sin(Math.min(this.serveTimer,0.5)*Math.PI)*0.025);s.ball.p.z=sign*1.19;
      if(this.inputs[server].serve&&this.serveTimer>0.12){this.inputs[server].serve=false;this.beginServe();}
      return;
    }
    this.stepBall(dt);
  }

  private updatePaddles(dt:number):void{
    for(let side=0 as Side;side<=1;side=(side+1) as Side){
      const p=this.state.paddles[side],input=this.inputs[side];
      p.prevX=p.x;p.prevY=p.y;p.prevZ=p.z;
      // Human racket-head speed is materially higher than a walking hand target.
      // These caps allow compact 8–11 m/s strokes while preventing teleport hits.
      const maxSpeed=10.5, maxAccel=70;
      const desired={x:clamp((input.x-p.x)*15,-maxSpeed,maxSpeed),y:clamp((input.y-p.y)*15,-maxSpeed,maxSpeed),z:clamp((input.z-p.z)*15,-maxSpeed,maxSpeed)};
      p.vx+=clamp(desired.x-p.vx,-maxAccel*dt,maxAccel*dt);
      p.vy+=clamp(desired.y-p.vy,-maxAccel*dt,maxAccel*dt);
      p.vz+=clamp(desired.z-p.vz,-maxAccel*dt,maxAccel*dt);
      p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;
      p.cooldown=Math.max(0,p.cooldown-dt);
      p.power=false;p.slice=false;
    }
  }

  private stepBall(dt:number):void{
    const b=this.state.ball,prev={...b.p};
    const speed=length(b.v);
    // Quadratic drag and spin-dependent Magnus force. Spin is angular velocity in rad/s.
    const dragScale=AIR_DRAG*speed;
    const magnus=cross(b.spin,b.v);
    b.v.x+=(-dragScale*b.v.x+MAGNUS*magnus.x)*dt;
    b.v.y+=(-GRAVITY-dragScale*b.v.y+MAGNUS*magnus.y)*dt;
    b.v.z+=(-dragScale*b.v.z+MAGNUS*magnus.z)*dt;
    b.p.x+=b.v.x*dt;b.p.y+=b.v.y*dt;b.p.z+=b.v.z*dt;
    const spinDamp=Math.max(0,1-AIR_SPIN_DECAY*dt);
    b.spin.x*=spinDamp;b.spin.y*=spinDamp;b.spin.z*=spinDamp;

    if(this.crossedNet(prev.z,b.p.z)){
      const t=clamp(-prev.z/(b.p.z-prev.z),0,1),y=prev.y+(b.p.y-prev.y)*t,x=prev.x+(b.p.x-prev.x)*t;
      if(Math.abs(x)<TABLE.width/2+0.08&&y-BALL_RADIUS<TABLE.y+TABLE.netHeight&&y+BALL_RADIUS>TABLE.y){
        this.emit("net",b.lastHitter,b.p);
        if(b.serve&&b.bounces===1&&b.firstBounce===b.lastHitter){this.state.message="Лет — подача переигрывается";this.prepareServe("Лет — повторная подача");}
        else this.awardPoint(other(b.lastHitter),"Мяч задел сетку");return;
      }
    }
    const tableY=TABLE.y+BALL_RADIUS;
    if(prev.y>=tableY&&b.p.y<=tableY&&b.v.y<0&&Math.abs(b.p.x)<=TABLE.width/2&&Math.abs(b.p.z)<=TABLE.length/2){
      const t=clamp((prev.y-tableY)/(prev.y-b.p.y),0,1);
      b.p.x=prev.x+(b.p.x-prev.x)*t;b.p.z=prev.z+(b.p.z-prev.z)*t;b.p.y=tableY;
      this.onTableBounce();if(this.state.phase!=="rally")return;
      this.applyTableImpulse();this.emit("bounce",b.lastHitter,b.p);
    }
    if(this.state.phase!=="rally")return;
    this.checkPaddleHits(prev);
    if(this.state.phase!=="rally")return;
    if(b.p.y<0.08||Math.abs(b.p.z)>2.25||Math.abs(b.p.x)>1.55)this.onOut();
  }

  private applyTableImpulse():void{
    const b=this.state.ball;
    const normalVelocity=b.v.y;
    // A legal serve must bounce on the receiver's half before it can be returned.
    // Use a deliberately lower first-bounce restitution on serves so the second
    // bounce happens inside the receiving court, before the racket contact plane.
    const restitution=b.serve&&b.bounces===1?0.76:TABLE_RESTITUTION;
    const normalImpulse=BALL_MASS*(1+restitution)*Math.abs(normalVelocity);
    b.v.y=Math.abs(normalVelocity)*restitution;
    // Contact point is one radius below the centre; friction couples horizontal velocity and spin.
    const r={x:0,y:-BALL_RADIUS,z:0};
    const rotational=cross(b.spin,r);
    const slip={x:b.v.x+rotational.x,y:0,z:b.v.z+rotational.z};
    let jx=-BALL_MASS*slip.x*0.72,jz=-BALL_MASS*slip.z*0.72;
    const maxJ=TABLE_FRICTION*normalImpulse,j=Math.hypot(jx,jz);
    if(j>maxJ&&j>0){jx*=maxJ/j;jz*=maxJ/j;}
    b.v.x+=jx/BALL_MASS;b.v.z+=jz/BALL_MASS;
    const angular=cross(r,{x:jx,y:0,z:jz});
    b.spin.x+=angular.x/BALL_INERTIA;b.spin.z+=angular.z/BALL_INERTIA;
    // A little residual skid and spin loss at impact, not an artificial fixed trajectory.
    b.spin.x*=0.91;b.spin.y*=0.94;b.spin.z*=0.91;
  }

  private crossedNet(a:number,b:number):boolean{return(a>0&&b<=0)||(a<0&&b>=0);}
  private onTableBounce():void{
    const b=this.state.ball,bounceSide:Side=b.p.z>=0?0:1;b.bounces++;
    if(b.bounces===1)b.firstBounce=bounceSide;
    if(b.serve){
      if(b.bounces===1&&bounceSide!==b.lastHitter)this.awardPoint(other(b.lastHitter),"Ошибка на подаче");
      else if(b.bounces===2&&bounceSide===b.lastHitter)this.awardPoint(other(b.lastHitter),"Подача не пересекла корт");
      else if(b.bounces>=3)this.awardPoint(b.lastHitter,"Мяч не был принят");return;
    }
    const expected=other(b.lastHitter);
    if(b.bounces===1&&bounceSide!==expected)this.awardPoint(expected,"Мяч не попал на чужую половину");
    else if(b.bounces>=2)this.awardPoint(b.lastHitter,"Два отскока — очко");
  }

  private checkPaddleHits(prevBall:Vec3):void{
    const b=this.state.ball;
    for(let side=0 as Side;side<=1;side=(side+1) as Side){
      const p=this.state.paddles[side];if(p.cooldown>0||side===b.lastHitter)continue;
      const sign=sideSign(side);
      const prevRel=prevBall.z-p.prevZ,nextRel=b.p.z-p.z;
      const crossed=sign>0?(prevRel<=0&&nextRel>=0):(prevRel>=0&&nextRel<=0);
      if(!crossed)continue;
      const denom=prevRel-nextRel,t=Math.abs(denom)>1e-7?clamp(prevRel/denom,0,1):0.5;
      const bx=prevBall.x+(b.p.x-prevBall.x)*t,by=prevBall.y+(b.p.y-prevBall.y)*t;
      const px=p.prevX+(p.x-p.prevX)*t,py=p.prevY+(p.y-p.prevY)*t;
      // Realistic blade footprint (roughly 17 x 16 cm), expanded by the 4 cm ball diameter.
      const dx=(bx-px)/0.145,dy=(by-py)/0.14;
      if(dx*dx+dy*dy>1)continue;
      if(b.serve&&b.bounces<2){this.awardPoint(b.lastHitter,"Приём до отскока");return;}
      if(!b.serve&&b.bounces<1){this.awardPoint(b.lastHitter,"Удар с лёта запрещён");return;}
      this.hitBall(side,{x:bx,y:by,z:p.z});return;
    }
  }

  private hitBall(side:Side,contact:Vec3):void{
    const s=this.state,b=s.ball,p=s.paddles[side],sign=sideSign(side);
    // The blade naturally tilts with the racket's measured swing velocity.
    const normal=normalize({x:clamp(p.vx*0.08,-0.38,0.38),y:clamp(-p.vy*0.20,-0.48,0.48),z:-sign});
    const relativeNormal=dot({x:b.v.x-p.vx,y:b.v.y-p.vy,z:b.v.z-p.vz},normal);
    // Forgiving arcade contact: a valid face overlap still returns the ball when
    // the racket is tracking at nearly the same speed as the incoming ball.
    if(relativeNormal>=0.35)return;
    const impactNormal=Math.min(relativeNormal,-1.15);
    const normalImpulse=BALL_MASS*(1+PADDLE_RESTITUTION)*(-impactNormal);
    b.v.x-=((1+PADDLE_RESTITUTION)*impactNormal)*normal.x;
    b.v.y-=((1+PADDLE_RESTITUTION)*impactNormal)*normal.y;
    b.v.z-=((1+PADDLE_RESTITUTION)*impactNormal)*normal.z;
    // Coulomb-limited tangential impulse: moving the racket across/under the ball
    // creates side/top/back spin automatically. No spin modifier buttons are used.
    const arm={x:-normal.x*BALL_RADIUS,y:-normal.y*BALL_RADIUS,z:-normal.z*BALL_RADIUS};
    const rotational=cross(b.spin,arm);
    const contactVelocity={x:b.v.x+rotational.x-p.vx,y:b.v.y+rotational.y-p.vy,z:b.v.z+rotational.z-p.vz};
    const normalPart=dot(contactVelocity,normal);
    const slip={x:contactVelocity.x-normalPart*normal.x,y:contactVelocity.y-normalPart*normal.y,z:contactVelocity.z-normalPart*normal.z};
    let impulse={x:-BALL_MASS*slip.x*0.82,y:-BALL_MASS*slip.y*0.82,z:-BALL_MASS*slip.z*0.82};
    const j=length(impulse),maxJ=PADDLE_FRICTION*normalImpulse;
    if(j>maxJ&&j>0){const scale=maxJ/j;impulse={x:impulse.x*scale,y:impulse.y*scale,z:impulse.z*scale};}
    b.v.x+=impulse.x/BALL_MASS;b.v.y+=impulse.y/BALL_MASS;b.v.z+=impulse.z/BALL_MASS;
    const angular=cross(arm,impulse);
    b.spin.x+=angular.x/BALL_INERTIA;b.spin.y+=angular.y/BALL_INERTIA;b.spin.z+=angular.z/BALL_INERTIA;
    // Small torsional damping models the rubber/ball contact patch.
    b.spin.x*=0.94;b.spin.y*=0.94;b.spin.z*=0.94;
    b.lastHitter=side;b.serve=false;b.bounces=0;b.firstBounce=null;p.cooldown=0.11;
    s.rallyHits++;s.message="Удар";this.emit("hit",side,contact);
  }

  private beginServe():void{
    const s=this.state,server=s.server,sign=sideSign(server),p=s.paddles[server],b=s.ball;
    // Click-triggered serve. Launch angle and spin are coupled to the actual racket motion.
    const face=normalize({x:clamp(p.vx*0.025,-0.16,0.16),y:clamp(-p.vy*0.025,-0.16,0.16),z:-sign});
    const vx=clamp(p.vx*0.30+(this.random()-0.5)*0.12,-1.5,1.5);
    const vz=-sign*(5.15+Math.min(0.8,Math.hypot(p.vx,p.vy)*0.10));
    // A low, descending service contact: first bounce on the server's half,
    // then the ball clears the net and drops on the receiver's half.
    const vy=-1.48+Math.max(0,p.vy)*0.055;
    b.p={x:clamp(p.x,-0.65,0.65),y:1.10,z:sign*1.19};
    b.v={x:vx+face.x*0.25,y:vy+face.y*0.12,z:vz};
    b.spin={x:-p.vy*18,y:p.vx*20,z:(p.vx-p.vy)*3};
    b.bounces=0;b.firstBounce=null;b.serve=true;b.lastHitter=server;
    s.phase="rally";s.message=`Подаёт ${server===0?"первый":"второй"} игрок`;s.rallyHits=1;this.emit("serve",server,b.p);
  }

  private onOut():void{
    const b=this.state.ball,hitter=b.lastHitter;
    if(b.serve){const valid=b.bounces>=2&&b.firstBounce===hitter;this.awardPoint(valid?hitter:other(hitter),valid?"Мяч не был принят":"Ошибка на подаче");return;}
    const expected=other(hitter),valid=b.bounces>=1&&b.firstBounce===expected;
    this.awardPoint(valid?hitter:other(hitter),valid?"Соперник не успел к мячу":"Мяч ушёл в аут");
  }
  private awardPoint(winner:Side,reason:string):void{
    const s=this.state;if(s.phase!=="rally")return;
    s.scores[winner]++;s.lastPoint=winner;s.phase="point";s.message=`${reason}. Очко игроку ${winner+1}`;
    s.ball.v={x:0,y:0,z:0};s.ball.spin={x:0,y:0,z:0};this.pointTimer=1.8;this.emit("point",winner,s.ball.p);
    const lead=Math.abs(s.scores[0]-s.scores[1]);
    if(s.scores[winner]>=11&&lead>=2){s.games[winner]++;this.newGame=true;this.pointTimer=2.5;s.message=`Партия игроку ${winner+1}: ${s.scores[0]}:${s.scores[1]}`;this.emit("game",winner);
      if(s.games[winner]>=2){s.phase="gameover";s.winner=winner;s.message=`Матч выиграл игрок ${winner+1}`;this.newGame=false;}}
  }
}
